using Aspire.Hosting.Testing;
using Xunit;

namespace MyApp.Tests;

public class AppHostTests
{
    [Fact]
    public async Task AppHost_Starts_Successfully()
    {
        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        await using var app = await builder.BuildAsync();
        await app.StartAsync();

        await app.WaitForResources().WaitAsync(TimeSpan.FromSeconds(60));
    }

    [Fact]
    public async Task AppHost_Resources_Have_No_Errors()
    {
        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        await using var app = await builder.BuildAsync();
        await app.StartAsync();

        var resourceNotificationService = app.Services
            .GetRequiredService<ResourceNotificationService>();

        await app.WaitForResources().WaitAsync(TimeSpan.FromSeconds(60));

        // Verify no resources are in a failed state
        var resourceEvents = resourceNotificationService.WatchAsync();
        await foreach (var evt in resourceEvents)
        {
            Assert.NotEqual("FailedToStart", evt.Snapshot.State?.Text);
            break; // Check initial state only
        }
    }
}

